private UUID proposal(TransactionPurpose purpose, String amount) {UUID tx = UUID.randomUUID(); service.propose(new CommitTransactionCommand(TENANT, COMMUNITY, UNIT, tx, purpose, List.of(new CommitTransactionCommand.Entry(A, amount), new CommitTransactionCommand.Entry(B, "-" + amount)), Map.of(), null)); return tx;}
private String payload(UUID tx) {return jdbc.queryForObject( "select authorization_payload from ostris.transaction_proposal where id=?", String.class, tx);}
private void addSigned(UUID tx, UUID account, UUID credentialId, KeyPair signer, String payload) throws Exception {service.addAccountEvidence(TENANT, tx, account, credentialId, sign(new OstrisWireCodec().authorizationMessage(new OstrisWireCodec().parse(payload)), signer));}
private Signer createSigner(long activation, Long revocation) throws Exception {KeyPair pair = KeyPairGenerator.getInstance("Ed25519").generateKeyPair(); UUID controllerId = UUID.randomUUID(), credentialId = UUID.randomUUID(); String publicKey = rawPublic(pair); jdbc.update( "insert into ostris.protocol_controller(id,tenant_id,community_id,activation_sequence,revocation_sequence) values(?,?,?,?,?)", controllerId, TENANT, COMMUNITY, activation, revocation); jdbc.update( "insert into ostris.credential(id,tenant_id,community_id,public_key_base64url,algorithm,activation_sequence,revocation_sequence) values(?,?,?,?, 'Ed25519',?,?)", credentialId, TENANT, COMMUNITY, publicKey, activation, revocation); jdbc.update( "insert into ostris.controller_credential_binding(credential_id,tenant_id,community_id,controller_id,public_key_base64url,activation_sequence,revocation_sequence) values(?,?,?,?,?,?,?)", credentialId, TENANT, COMMUNITY, controllerId, publicKey, activation, revocation); return new Signer(controllerId, credentialId, pair);}
private Signer createCredentialFor(UUID controllerId, long activation, Long revocation) throws Exception {KeyPair pair = KeyPairGenerator.getInstance("Ed25519").generateKeyPair(); UUID credentialId = UUID.randomUUID(); String publicKey = rawPublic(pair); jdbc.update( "insert into ostris.credential(id,tenant_id,community_id,public_key_base64url,algorithm,activation_sequence,revocation_sequence) values(?,?,?,?, 'Ed25519',?,?)", credentialId, TENANT, COMMUNITY, publicKey, activation, revocation); jdbc.update( "insert into ostris.controller_credential_binding(credential_id,tenant_id,community_id,controller_id,public_key_base64url,activation_sequence,revocation_sequence) values(?,?,?,?,?,?,?)", credentialId, TENANT, COMMUNITY, controllerId, publicKey, activation, revocation); return new Signer(controllerId, credentialId, pair);}
private UUID finalFinding() {UUID basis = UUID.randomUUID(); jdbc.update( "insert into ostris.finding(id,tenant_id,community_id,case_id,status,finality_sequence) values(?,?,?,?,'FINAL',0)", basis, TENANT, COMMUNITY, UUID.randomUUID()); jdbc.update( "insert into ostris.resolution_basis(id,tenant_id,community_id,basis_type,status,finality_sequence) values(?,?,?,'FINAL_FINDING','FINAL',0)", basis, TENANT, COMMUNITY); return basis;}
private UUID penaltyProposal(UUID basis, String amount) {UUID tx = UUID.randomUUID(); service.propose(new CommitTransactionCommand(TENANT, COMMUNITY, UNIT, tx, TransactionPurpose.PENALTY, List.of(new CommitTransactionCommand.Entry(A, amount), new CommitTransactionCommand.Entry(B, "-" + amount)), Map.of("finalFindingId", basis.toString()), null)); return tx;}
private String governanceSignature(UUID tx, UUID authority, UUID basis, Set<UUID> covered, KeyPair signer) throws Exception {return governanceSignature(tx, authority, ResolutionBasisType.FINAL_FINDING, basis, covered, signer);}
private String governanceSignature(UUID tx, UUID authority, ResolutionBasisType type, UUID basis, Set<UUID> covered, KeyPair signer) throws Exception {String accountPayload = payload(tx); com.fasterxml.jackson.databind.node.ObjectNode n = (com.fasterxml.jackson.databind.node.ObjectNode) new OstrisWireCodec().parse(accountPayload); n.put("authorityId", authority.toString()); n.put("authorityPolicyVersion", 1); com.fasterxml.jackson.databind.node.ArrayNode ca = n.putArray("coveredAccounts"); covered.stream().sorted().forEach(id -> ca.add(id.toString())); var rb = n.putObject("resolutionBasis"); rb.put("id", basis.toString()); rb.put("type", type.name()); return sign(new OstrisWireCodec().governanceAuthorizationMessage(n), signer);}
private void assertConstraintViolation(Runnable action) {jdbc.execute("savepoint expected_failure"); assertThrows(org.springframework.dao.DataAccessException.class, action::run); jdbc.execute("rollback to savepoint expected_failure"); jdbc.execute("release savepoint expected_failure");}
