@ParameterizedTest(name="REVERSAL structural reject: {0}") @ValueSource(strings={"wrong-amount","wrong-sign","extra-entry","wrong-order","wrong-existing-original","nonexistent-original","second-reversal","reversal-of-reversal"}) void reversalNegativeMatrixRejectsAtomically(String mode)throws Exception{UUID c=UUID.randomUUID(),d=UUID.randomUUID();jdbc.update("insert into ostris.account(id,tenant_id,community_id,unit_id,account_type,name,credit_floor) values(?,?,?,?,'INDIVIDUAL','C',-10000)",c,TENANT,COMMUNITY,UNIT);addControlPolicy(c);jdbc.update("insert into ostris.account(id,tenant_id,community_id,unit_id,account_type,name,credit_floor) values(?,?,?,?,'INDIVIDUAL','D',-10000)",d,TENANT,COMMUNITY,UNIT);addControlPolicy(d);List<CommitTransactionCommand.Entry> originalEntries=List.of(new CommitTransactionCommand.Entry(A,"100"),new CommitTransactionCommand.Entry(B,"-60"),new CommitTransactionCommand.Entry(c,"-40"));UUID original=exchange(originalEntries);signAll(original,List.of(A,B,c));service.commit(TENANT,original);List<CommitTransactionCommand.Entry> full=List.of(new CommitTransactionCommand.Entry(A,"-100"),new CommitTransactionCommand.Entry(B,"60"),new CommitTransactionCommand.Entry(c,"40"));UUID reference=original;if(mode.equals("wrong-existing-original")){reference=exchange(List.of(new CommitTransactionCommand.Entry(A,"10"),new CommitTransactionCommand.Entry(B,"-10")));signAll(reference,List.of(A,B));service.commit(TENANT,reference);}if(mode.equals("nonexistent-original"))reference=UUID.randomUUID();if(Set.of("second-reversal","reversal-of-reversal").contains(mode)){UUID first=governedProposal(TransactionPurpose.REVERSAL,full,Map.of("reversesTransactionId",original.toString()));signAll(first,List.of(A,B,c));service.commit(TENANT,first);if(mode.equals("reversal-of-reversal")){reference=first;full=originalEntries;}}List<CommitTransactionCommand.Entry> attempt=switch(mode){case "wrong-amount"->List.of(new CommitTransactionCommand.Entry(A,"-100"),new CommitTransactionCommand.Entry(B,"50"),new CommitTransactionCommand.Entry(c,"50"));case "wrong-sign"->List.of(new CommitTransactionCommand.Entry(A,"100"),new CommitTransactionCommand.Entry(B,"60"),new CommitTransactionCommand.Entry(c,"-160"));case "extra-entry"->List.of(new CommitTransactionCommand.Entry(A,"-100"),new CommitTransactionCommand.Entry(B,"60"),new CommitTransactionCommand.Entry(c,"39"),new CommitTransactionCommand.Entry(d,"1"));case "wrong-order"->List.of(new CommitTransactionCommand.Entry(B,"60"),new CommitTransactionCommand.Entry(A,"-100"),new CommitTransactionCommand.Entry(c,"40"));default->full;};UUID tx=governedProposal(TransactionPurpose.REVERSAL,attempt,Map.of("reversesTransactionId",reference.toString()));signAll(tx,attempt.stream().map(CommitTransactionCommand.Entry::accountId).distinct().toList());assertThrows(ProtocolException.class,()->service.commit(TENANT,tx));assertNoEconomicEffects(tx);}
